using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class AuthorMinimapCorner{
public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();var rows=new JArray();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var l=h.Layout;var r=l.MapPanel;r.anchorMin=r.anchorMax=r.pivot=Vector2.one;l.Apply(true);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");rows.Add(new JObject{{"scene",name},{"anchor",r.anchorMax.ToString()},{"pivot",r.pivot.ToString()},{"position",r.anchoredPosition.ToString()}});}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}File.WriteAllText("Docs/Measurements/2026-10-03-minimap-top-right/saved-scenes.json",rows.ToString());return "Saved both top-right minimap anchors";}}
